{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 조례상 장애인 주차요금 감면과 다둥이 행복카드 감면 동시 적용 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "두 감면을 동시에 적용할 수 없습니다. 서울특별시 주차장 설치 및 관리 조례 제7조 제3항은 둘 이상의 주차요금 감면사유에 해당하는 때에는 그 중 감면율이 높은 하나만 적용한다고 정하고 있습니다.",
          "b_ids": "주차장:제7조제3항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "장애인·다둥이 행복카드 감면 모두 충족 시 적용되는 감면율",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "장애인 감면율(100분의 80)이 다둥이 행복카드 감면율(100분의 50)보다 높으므로, 감면율이 높은 장애인 감면만 적용되어 주차요금의 100분의 80을 할인받습니다.",
          "b_ids": "주차장:제7조제3항, 주차장:제7조제1항제1호, 주차장:제7조제1항제7호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
